-- B2.1 contract vectors only; no server migration or hosted access.
-- Run later against a manager-approved disposable PostgreSQL database.
-- Expected JSONB text is a pinned assertion, not evidence of an executed SQL test.
-- PostgreSQL built-in sha256(bytea); pgcrypto is not required.
BEGIN;
DO $codec_vectors$
DECLARE
  vector record;
  input_bytes bytea;
  stored_bytes bytea;
  actual_text text;
BEGIN
  FOR vector IN SELECT * FROM (VALUES
    ('unicode-whitespace-scale', '207b0a20226c6f6e674b6579223a20226361665c753030653920f09fa9ba222c202262223a205b31652d372c20312e323330305d2c202261223a20224f275265696c6c795c6e6c696e6522200a7d', '7b2261223a20224f275265696c6c795c6e6c696e65222c202262223a205b302e303030303030312c20312e323330305d2c20226c6f6e674b6579223a2022636166c3a920f09fa9ba227d', '96b488395fa4574f5935b169b99cecf6089a51eb154897515391ac6febe699e8', 'da71416d68835350d04fcb7fe8eff3e5f1db1ceb627b135883827766e3d4d0e2', 78, 74),
    ('utf8-key-order', '7b226161223a322c2262223a312c22c3a9223a332c22f09f9880223a342c2261223a357d', '7b2261223a20352c202262223a20312c20226161223a20322c2022c3a9223a20332c2022f09f9880223a20347d', '1cb2d9e318f5c5cf6f27a15a0899385a4001cb347ae40ce36062fe9e3b1b53ab', '319c5807806ea1e3127c31e940f75214baa0504ec06a89d1cd5c7666249f1d25', 36, 45),
    ('safe-number-extremes', '7b2274696e79223a35652d3332342c226672616374696f6e223a302e33303030303030303030303030303030342c226d696e223a2d393030373139393235343734303939312c226d6178223a393030373139393235343734303939312c22657870223a31652d372c226d6f6e6579223a3132333435363738392e30317d', '', 'b1e36c21ca971b91d5c3767624e17e5e6723be28a8c044385c505f626d55127e', '77135e54da07e797f59b64bacf11011a8d7924d161949ee882ef5b6c058a698a', 125, 461),
    ('escaped-and-distinct-unicode', '7b227a223a2271756f74655c2220736c6173685c5c207461625c74222c2261223a22655c7530333031222c226e223a225c7530306539222c22756e69636f6465223a22e697a5e69cac227d', '7b2261223a202265cc81222c20226e223a2022c3a9222c20227a223a202271756f74655c2220736c6173685c5c207461625c74222c2022756e69636f6465223a2022e697a5e69cac227d', '76f812c52ea7a30a60b83309f929a88b258a7049f9aa3bfe4b42ab48cb73cbf9', '22039c483785013d6ea67589e8d3b2963c315ed6e410cf0dc4afd640bd321d60', 75, 74),
    ('normalized-evidence-reference-layout', '', '', '8012f802284590fc0e944722fd385d1a8961777e5b0dcf27372f6a73dd8566bf', 'ab9409a6ff3f88861db1f65a41ccc932e384fcc27dd383712f32e382835ff5ce', 305, 332)
  ) AS vectors(id, input_hex, stored_hex, input_sha256, stored_sha256, input_bytes_count, stored_bytes_count)
  LOOP
    input_bytes := decode(vector.input_hex, 'hex');
    stored_bytes := decode(vector.stored_hex, 'hex');
    actual_text := (convert_from(input_bytes, 'UTF8')::jsonb)::text;
    IF actual_text <> convert_from(stored_bytes, 'UTF8') THEN
      RAISE EXCEPTION 'B2.1 canonical text mismatch: %', vector.id;
    END IF;
    IF encode(sha256(input_bytes), 'hex') <> vector.input_sha256
       OR encode(sha256(convert_to(actual_text, 'UTF8')), 'hex') <> vector.stored_sha256
       OR octet_length(input_bytes) <> vector.input_bytes_count
       OR octet_length(convert_to(actual_text, 'UTF8')) <> vector.stored_bytes_count THEN
      RAISE EXCEPTION 'B2.1 byte/hash mismatch: %', vector.id;
    END IF;
    IF convert_from(input_bytes, 'UTF8')::jsonb <> actual_text::jsonb THEN
      RAISE EXCEPTION 'B2.1 logical JSONB mismatch: %', vector.id;
    END IF;
  END LOOP;
  RAISE NOTICE 'PASS B2.1 golden JS/SQL vectors: 5';
END
$codec_vectors$;
ROLLBACK;
